  "output_head": "//! Bots are ordinary users with separately scoped ownership and API credentials.

use rusqlite::{Connection, params};

use crate::error::Result;
use crate::sql::{self, query_all, query_one};
use crate::{Account, Errors, NewUser, PasswordDigest, Role, Status, Tx, User};

// Deliberately not Debug: the code is a bearer credential.
#[derive(Clone)]
pub struct Bot {
    pub user: User,
    pub creator_id: i64,
    pub code: String,
    pub webhook_url: Option<String>,
    pub add_to_all_open_rooms: bool,
}

impl Bot {
    pub fn can_create(conn: &Connection, creator: &User) -> Result<bool> {
        if creator.role == Role::Administrator {
            return Ok(true);
        }
        let limit = Account::first(conn)?.ok_or(crate::Error::RecordNotFound("Account"))?.settings().bots_per_member();
        let count = sql::count(
            conn,
            "SELECT COUNT(*) FROM chat_bots b JOIN users u ON u.id = b.user_id WHERE b.creator_id = ? AND u.status = 0",
            [creator.id],
        )?;
        Ok(count < limit)
    }

    pub fn create(tx: &mut Tx<'_>, creator_id: i64, name: String, password_digest: PasswordDigest) -> Result<Self> {
        // Count and insert in the same write transaction, including a fresh role/settings check.
        if !Self::can_create(tx.conn(), &User::find(tx.conn(), creator_id)?)? {
            let mut errors = Errors::default();
            errors.add("bots", "have reached the limit");
            return Err(crate::Error::RecordInvalid(errors));
        }
        let user = User::create(tx, NewUser { name, password_digest: Some(password_digest), ..Default::default() })?;
        let code = sql::base58(32);
        tx.conn().execute("INSERT INTO chat_bots (user_id, creator_id, code) VALUES (?, ?, ?)", params![user.id, creator_id, code])?;
        Ok(Self { user, creator_id, code, webhook_url: None, add_to_all_open_rooms: false })
    }

    pub fn find(conn: &Connection, user_id: i64) -> Result<Self> {
        let (creator_id, code) = query_one(conn, "SELECT creator_id, code FROM chat_bots WHERE user_id = ?", [user_id], |row| {
            Ok((row.get(0)?, row.get(1)?))
        })?
        .ok_or(crate::Error::RecordNotFound("Bot"))?;
        let user = User::find_active(conn, user_id)?;
        let webhook_url = query_one(conn, "SELECT url FROM chat_bot_webhooks WHERE user_id = ?", [user_id], |row| row.get(0))?;
        let add_to_all_open_rooms =
            query_one(conn, "SELECT user_id FROM chat_bot_auto_join WHERE user_id = ?", [user_id], |row| row.get::<_, i64>(0))?
                .is_some();
        Ok(Self { user, creator_id, code, webhook_url, add_to_all_open_rooms })
    }

    pub fn set_add_to_all_open_rooms(&mut self, tx: &mut Tx<'_>, enabled: bool) -> Result<()> {
        if enabled {
            tx.conn().execute("INSERT INTO chat_bot_auto_join (user_id) VALUES (?) ON CONFLICT DO NOTHING", [self.user.id])?;
            let room_ids: Vec<i64> = query_all(tx.conn(), "SELECT id FROM rooms WHERE type = 'Rooms::Open'", [], |row| row.get(0))?;
            for room_id in room_ids {
                crate::Room::find(tx.conn(), room_id)?.grant_to(tx, &[self.user.id])?;
            }
        } else {
            tx.conn().execute("DELETE FROM chat_bot_auto_join WHERE user_id = ?", [self.user.id])?;
        }
        self.add_to_all_open_rooms = enabled;
        Ok(())
    }

    /// A first membership, not a room save or a re-addition. Keep this record even if
    /// membership is revoked, so a bot only receives one greeting opportunity per room.
    pub(crate) fn joined(tx: &mut Tx<'_>, user_id: i64, room_id: i64) -> Result<()> {
        let inserted = tx.conn().execute(
            "INSERT INTO chat_bot_room_joins (user_id, room_id)
             SELECT b.user_id, r.id FROM chat_bots b, rooms r
             WHERE b.user_id = ? AND r.id = ? AND r.type != 'Rooms::Direct'
             ON CONFLICT DO NOTHING",
            params![user_id, room_id],
        )?;
        if inserted != 0 {
            tx.emit_after_commit(crate::Event::BotJoined { user_id, room_id });
        }
        Ok(())
    }

    pub fn set_webhook(&mut self, tx: &mut Tx<'_>, url: Option<&str>) -> Result<()> {
        match url {
            Some(url) => {
                tx.conn().execute(
                    "INSERT INTO chat_bot_webhooks (user_id, url) VALUES (?, ?) ON CONFLICT(user_id) DO UPDATE SET url = excluded.url",
                    params![self.user.id, url],
                )?;
            }
            None => {
                tx.conn().execute("DELETE FROM chat_bot_webhooks WHERE user_id = ?", [self.user.id])?;
            }
        }
        self.webhook_url = url.map(str::to_owned);
        Ok(())
    }

    pub fn managed_by(conn: &Connection, manager: &User) -> Result<Vec<Self>> {
        let ids: Vec<i64> = query_all(
            conn,
            "SELECT b.user_id FROM chat_bots b JOIN users u ON u.id = b.user_id WHERE u.status = 0 AND (? OR b.creator_id = ?) ORDER BY u.na",
  "output_tail": "nd never retried by the in-process job runner.
pub async fn joined(app: App, event: campfire_db::Event) -> anyhow::Result<()> {
    let campfire_db::Event::BotJoined { user_id, room_id } = event else { return Ok(()) };
    let delivery = app
        .db
        .read_offloaded(move |conn| {
            let bot = match Bot::find(conn, user_id) {
                Ok(bot) if bot.webhook_url.is_some() => bot,
                Ok(_) | Err(campfire_db::Error::RecordNotFound(_)) => return Ok(None),
                Err(error) => return Err(error),
            };
            let Some(room) = Room::find_for_user(conn, user_id, room_id)? else { return Ok(None) };
            if room.room_type == campfire_db::RoomType::Direct {
                return Ok(None);
            }
            let payload = json!({
                "event": "joined",
                "room": { "id": room.id, "name": room.name,
                    "reply_to": format!("/rooms/{}/{}/messages", room.id, bot.code) }
            });
            Ok(Some(Delivery { bot, room, payload }))
        })
        .await?;
    if let Some(delivery) = delivery {
        // There is no request host for database-triggered jobs. Broadcast relative URLs.
        deliver(&app, delivery, String::new()).await?;
    }
    Ok(())
}

async fn deliver(app: &App, delivery: Delivery, base_url: String) -> anyhow::Result<()> {
    let url = delivery.bot.webhook_url.as_deref().context("missing webhook URL")?;
    let (uri, endpoint) = endpoint(url)?;
    let mut request = http::Request::net_http(
        hyper::Method::POST,
        http::request_uri(&uri),
        Some(endpoint.host_header()),
        vec![("Content-Type".into(), "application/json".into())],
    );
    request.body = serde_json::to_vec(&delivery.payload)?;
    let reply = tokio::time::timeout(TIMEOUT, async {
        let response = http::exchange(&Network::system(), &endpoint, request, &http::Timeouts { open: TIMEOUT, read: TIMEOUT }).await?;
        if response.status == 204 {
            return Ok(None);
        }
        if response.status != 200 {
            bail!("webhook returned HTTP {}", response.status);
        }
        let content_type = response.content_type().unwrap_or_default().to_ascii_lowercase();
        if !matches!(content_type.as_str(), "text/plain" | "text/html") {
            return Ok(None);
        }
        let http::Body::Complete(bytes) = response.read_body(MAX_REPLY_BYTES).await? else {
            bail!("webhook reply too large");
        };
        let body = String::from_utf8(bytes).context("webhook reply is not UTF-8")?;
        if body.trim().is_empty() {
            return Ok(None);
        }
        let body = if content_type == "text/plain" { ruby_compat::erb::html_escape(&body).replace('\n', "<br>") } else { body };
        Ok::<_, anyhow::Error>(Some(body))
    })
    .await
    .context("webhook timed out")??;
    let Some(body) = reply else { return Ok(()) };
    let body = messages::canonicalize_body(app, body, None).await.map_err(|error| anyhow::anyhow!(error.to_string()))?;
    let bot = delivery.bot;
    let room = delivery.room;
    let room_id = room.id;
    let message = app
        .db
        .write(move |tx| {
            // Recheck access after the HTTP call: deletion, webhook removal, or membership revocation
            // while waiting must not grant the callback permission to post.
            let current = match Bot::find(tx.conn(), bot.user.id) {
                Ok(current) => current,
                Err(campfire_db::Error::RecordNotFound(_)) => return Ok(None),
                Err(error) => return Err(error),
            };
            if current.webhook_url != bot.webhook_url
                || current.code != bot.code
                || Room::find_for_user(tx.conn(), bot.user.id, room_id)?.is_none()
            {
                return Ok(None);
            }
            Message::create(tx, NewMessage { room_id, creator_id: bot.user.id, body: Some(body), ..Default::default() }).map(Some)
        })
        .await?;
    if let Some(message) = message {
        messages::broadcast_create_at(app, &room, &message, base_url)
            .await
            .map_err(|error| anyhow::anyhow!(error.to_string()))?;
    }
    Ok(())
}

